#r @"Q:/repos/funnysharp/.worktrees/goal24-complete-pr/src/FunnySharp/bin/Release/net10.0/FunnySharp.dll";;
open System;;
open System.Collections.Generic;;
open FunnySharp;;
let source = [Unchecked.defaultof<Result<int,string>>];;
let actual = SequenceExtensions.Traverse<Result<int,string>,int,string>(source, Func<Result<int,string>,Result<int,string>>(fun _ -> Result<int,string>.Success(7)));;
let mutable values = Unchecked.defaultof<IReadOnlyList<int>>;;
let success = actual.TryGetValue(&values);;
if not success || values.Count <> 1 || values.[0] <> 7 then failwith "Unexpected traversal outcome";;
printfn "TRAVERSE_DEFAULT_SOURCE success=%b count=%d value=%d exception=none" success values.Count values.[0];;
exit 0;;
